code_example:
// Wrong: the type is in the label, the state is in the label, and the hint
// carries information the user needs — hints can be switched off.
Button(action: toggle) { Image(systemName: icon) }
  .accessibilityLabel(isOn ? "Favourite button, on" : "Favourite button, off")
  .accessibilityHint("This is the only way to save an article")

// Right: label names it, value carries the state, the trait carries behaviour
Button(action: toggle) { Image(systemName: icon) }
  .accessibilityLabel("Favourite")                       // spoken first
  .accessibilityValue(isOn ? "On" : "Off")               // spoken second, changes alone
  .accessibilityHint("Saves the article to your list")   // spoken last, may be silenced

// A heading you built from Text has no trait to infer — the rotor needs to be told
Text(section.title)
  .font(.title2)
  .accessibilityAddTraits(.isHeader)

// A ticker: the trait tells VoiceOver the value moves without an announcement
Text(price.formatted(.currency(code: "USD")))
  .accessibilityLabel("Current price")
  .accessibilityValue(price.formatted(.currency(code: "USD")))
  .accessibilityAddTraits(.updatesFrequently)

// UIKit: the same four properties, spoken in the same order
starControl.accessibilityLabel = "Rating"
starControl.accessibilityValue = "4 stars"
starControl.accessibilityTraits = [.button]
starControl.accessibilityHint = "Opens the review form"

// Five stops, four of them fragments: "photo", "Nimbus Runner", "$129", "New", "heart"
HStack {
  AsyncImage(url: product.imageURL)
  VStack(alignment: .leading) {
    Text(product.name)
    Text(product.price.formatted(.currency(code: "USD")))
    if product.isNew { NewBadge() }
  }
  Spacer()
  Button { toggleSaved() } label: { Image(systemName: saved ? "heart.fill" : "heart") }
}

// One stop that reads like a sentence, with the swallowed button back on the rotor
HStack {
  AsyncImage(url: product.imageURL)
    .accessibilityHidden(true)          // decorative: hide it *before* combining
  VStack(alignment: .leading) { /* ... */ }
  Spacer()
  Button { toggleSaved() } label: { Image(systemName: saved ? "heart.fill" : "heart") }
}
.accessibilityElement(children: .combine)
.accessibilityLabel("\(product.name), \(product.price.formatted(.currency(code: "USD")))")
.accessibilityAddTraits(.isButton)
.accessibilityAction(named: "Save") { toggleSaved() }

// Three independent controls stay reachable — group them, do not merge them
HStack { PlayButton(); ShuffleButton(); RepeatButton() }
  .accessibilityElement(children: .contain)

// UIKit: making the container an element hides everything inside it automatically
cardView.isAccessibilityElement = true
cardView.accessibilityLabel = "\(product.name), \(priceText)"
cardView.accessibilityTraits = .button

// SwiftUI: declaration order is the reading order, and a ZStack breaks the illusion
ZStack(alignment: .topLeading) {
  CoverArt(album: album)
  VStack(alignment: .leading) {
    Text(album.price).accessibilitySortPriority(1)   // drawn first, read last
    Text(album.title).accessibilitySortPriority(2)   // higher priority is read first
  }
}
.accessibilityElement(children: .contain)  // priorities only sort within one container

// Sort priority never moves an element out of its group — this does nothing at all
VStack {
  Header()
  Details().accessibilitySortPriority(10)  // still read after Header
}

// A hand-rolled overlay has to hide the page behind it, or swiping walks into it
SheetContent()
  .accessibilityAddTraits(.isModal)

// UIKit: an explicit array replaces the geometric order — anything omitted is gone
override func layoutSubviews() {
  super.layoutSubviews()
  accessibilityElements = [titleLabel, priceLabel, subtitleLabel, buyButton]
}

// Covered, decorative or off-screen views leave the tree rather than sit behind
watermarkView.accessibilityElementsHidden = true
customAlertView.accessibilityViewIsModal = true

// Custom actions land on the Actions rotor — and on Switch Control and Full Keyboard Access
MessageRow(message: message)
  .accessibilityAction(named: "Delete") { delete(message) }
  .accessibilityAction(named: "Mark as read") { markRead(message) }

// List's own swipe actions are exposed for free — no custom action needed
List {
  ForEach(messages) { message in
    MessageRow(message: message)
      .swipeActions { Button("Delete", role: .destructive) { delete(message) } }
  }
}

// Screen-level gestures: two-finger scrub to leave, two-finger double tap for "the" action
CustomSheet()
  .accessibilityAction(.escape) { dismiss() }
  .accessibilityAction(.magicTap) { togglePlayback() }

// The adjustable action supplies the trait, so the up/down swipe stops meaning
// "next element" and starts driving the value.
VolumeDial(value: $volume)
  .accessibilityLabel("Volume")
  .accessibilityValue("\(Int(volume * 100)) percent")   // a unit, not a bare number
  .accessibilityAdjustableAction { direction in
    switch direction {
    case .increment: volume = min(volume + 0.05, 1)
    case .decrement: volume = max(volume - 0.05, 0)
    @unknown default: break
    }
  }

// UIKit: the same two mechanisms, spelled differently
cell.accessibilityCustomActions = [
  UIAccessibilityCustomAction(name: "Delete") { [weak self] _ in
    self?.delete(message)
    return true
  }
]

final class RatingControl: UIControl {
  override func accessibilityIncrement() { rating = min(rating + 1, 5) }
  override func accessibilityDecrement() { rating = max(rating - 1, 1) }
}

// Wrong: a toast that resets the user's place and re-reads the whole screen
func didSave() {
  UIAccessibility.post(notification: .screenChanged, argument: "Saved")
}

// Right: speak, and leave focus where the user put it
func didSave() {
  UIAccessibility.post(notification: .announcement, argument: "Draft saved")
}

// iOS 17+: say whether it may interrupt, so it is not swallowed mid-sentence
var message = AttributedString("Upload failed")
message.accessibilitySpeechAnnouncementPriority = .high
AccessibilityNotification.Announcement(message).post()

// New rows appeared below: re-read the layout without moving focus
UIAccessibility.post(notification: .layoutChanged, argument: nil)

// Move focus on purpose — an error the user has to fix before continuing
UIAccessibility.post(notification: .layoutChanged, argument: emailErrorLabel)

// The one honest use of .screenChanged: you swapped the context yourself
UIAccessibility.post(notification: .screenChanged, argument: newPage.titleLabel)

// Often the right answer is no notification at all: VoiceOver re-reads the value
// of the focused element after the user's own action.
Stepper("Quantity", value: $quantity, in: 1...9)
  .accessibilityValue("\(quantity)")

// Do not gate behaviour on isVoiceOverRunning — an announcement with VoiceOver
// off is already a no-op, and branching here is how screens drift apart.

struct InboxRow: View {
  @Environment(\.dynamicTypeSize) private var typeSize
  @ScaledMetric(relativeTo: .headline) private var avatar: CGFloat = 40  // grows with text

  var body: some View {
    let layout = typeSize.isAccessibilitySize
      ? AnyLayout(VStackLayout(alignment: .leading, spacing: 4))   // reflow, do not shrink
      : AnyLayout(HStackLayout(alignment: .center, spacing: 12))

    layout {
      Avatar().frame(width: avatar, height: avatar)
      VStack(alignment: .leading) {
        Text(item.title).font(.headline)                    // a text style scales for free
        Text(item.subtitle)
          .font(.custom("Brand", size: 15, relativeTo: .subheadline))
      }
    }
    .frame(minHeight: 44)   // minimum — .frame(height: 44) is the clipping bug
  }
}

// Wrong: shrinking exactly the text the user asked to enlarge
Text(item.title).lineLimit(1).minimumScaleFactor(0.5)

// Clamp only what cannot reflow — a chart axis, a dense badge
ChartAxisLabels()
  .dynamicTypeSize(...DynamicTypeSize.accessibility1)

// The one font API that opts out of Dynamic Type completely
Text("©").font(.custom("Brand", fixedSize: 11))

// UIKit: a scaled font and a scaled constant are two separate jobs
label.font = UIFontMetrics(forTextStyle: .body).scaledFont(for: brandFont)
label.adjustsFontForContentSizeCategory = true
label.numberOfLines = 0
topSpacing.constant = UIFontMetrics(forTextStyle: .body).scaledValue(for: 16)

#Preview("AX5") {
  InboxRow().environment(\.dynamicTypeSize, .accessibility5)
}

struct Hero: View {
  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  @Environment(\.accessibilityReduceTransparency) private var reduceTransparency
  @Environment(\.colorSchemeContrast) private var contrast
  @Environment(\.legibilityWeight) private var legibilityWeight

  var body: some View {
    Banner()
      // Reduce Motion means a cross-fade, not a jump cut and not a dropped frame
      .animation(reduceMotion ? .easeInOut(duration: 0.2) : .bouncy, value: isOpen)
      .offset(y: reduceMotion ? 0 : parallaxOffset)
      // The system swaps its own materials; a hand-rolled blur is yours to swap
      .background(reduceTransparency ? AnyShapeStyle(Color.cardBackground)
                                     : AnyShapeStyle(.ultraThinMaterial))
      .overlay {
        RoundedRectangle(cornerRadius: 12)
          .stroke(.separator, lineWidth: contrast == .increased ? 2 : 1)
      }
      // System fonts embolden themselves; a brand family needs the heavier face
      .font(legibilityWeight == .bold ? .custom("Brand-Semibold", size: 17)
                                      : .custom("Brand-Regular", size: 17))
  }
}

// UIKit: read the flag, and subscribe to the change so a live toggle is honoured
if UIAccessibility.isReduceMotionEnabled { confettiView.stop() }

NotificationCenter.default.addObserver(
  forName: UIAccessibility.reduceTransparencyStatusDidChangeNotification,
  object: nil, queue: .main
) { [weak self] _ in self?.applyBackground() }

// Flip them for a screenshot run without touching Settings by hand:
// xcrun simctl ui booted increase_contrast enabled
// xcrun simctl ui booted content_size accessibility-extra-extra-extra-large

#Preview("Reduce Motion") {
  Hero().environment(\.accessibilityReduceMotion, true)
}

final class CheckoutAccessibilityTests: XCTestCase {
  func testCheckoutPassesTheAudit() throws {
    let app = XCUIApplication()
    app.launch()
    app.buttons["Cart"].tap()

    // The same checks the Inspector runs, as a test failure
    try app.performAccessibilityAudit()
  }

  func testCartAuditIgnoringOneKnownIssue() throws {
    let app = XCUIApplication()
    app.launch()

    try app.performAccessibilityAudit(for: [.dynamicType, .contrast, .hitRegion]) { issue in
      // Returning true means "handled, do not fail": the promo stripe is decorative
      // and ships clipped by design.
      issue.element?.identifier == "promoStripe"
    }
  }
}

// The audit is happy with all of this — a human is not:
Button(action: checkout) { Image(systemName: "cart") }
  .accessibilityLabel("Button")        // present, meaningless — passes .elementDetection

Text(total.formatted(.currency(code: "USD")))
  .foregroundStyle(isOverdue ? .red : .primary)   // colour is the only signal, contrast is fine

CardView(card: card)
  .onLongPressGesture { showActions() }  // no .accessibilityAction(named:) — unreachable

// And the sequence no static audit can see:
// dismiss a sheet, and nothing ever posts .layoutChanged, so focus lands nowhere useful.

// Wrong: hue is the entire message
HStack {
  Circle().fill(order.isPaid ? .green : .red).frame(width: 10, height: 10)
  Text(order.number)
}

// Right: shape + word + an accessible value, and the dot stops being a swipe stop
struct OrderRow: View {
  @Environment(\.accessibilityDifferentiateWithoutColor) private var differentiate
  let order: Order

  var body: some View {
    HStack {
      Image(systemName: order.isPaid ? "checkmark.circle.fill" : "exclamationmark.triangle.fill")
        .foregroundStyle(order.isPaid ? .green : .red)   // colour is the bonus, not the signal
        .accessibilityHidden(true)
      Text(order.number)
      Spacer()
      if differentiate || !order.isPaid {
        Text(order.isPaid ? "Paid" : "Overdue").font(.caption)
      }
    }
    .accessibilityElement(children: .combine)
    .accessibilityValue(order.isPaid ? "Paid" : "Overdue")
  }
}

// A named colour with a High Contrast variant in the asset catalog: the system picks it
// when Increase Contrast is on, so the 4.5:1 pair is the one you shipped for that mode.
Text("Overdue").foregroundStyle(Color("StatusWarning"))

// UIKit: compute contrast against what is actually drawn, not against the dynamic colour
let drawn = UIColor(named: "StatusWarning")!.resolvedColor(with: traitCollection)

// Extractable: the compiler sees a literal and writes it into Localizable.xcstrings
Text("Save")                                            // key "Save"
Button("Delete", role: .destructive) { delete() }
let msg = String(localized: "Order \(number) shipped",
                 comment: "Confirmation banner; number is an order id like A-1024")

// Not extractable: nothing here is a literal, so no catalog entry is ever created
Text(viewModel.title)                                   // ships the source language
let key = "greeting_\(kind)"
Text(LocalizedStringKey(key))                           // resolves only if the key exists

// A framework or SPM target looks up in its own bundle, not the app's
Text("Save", bundle: .module)
String(localized: "Save", table: "Checkout", bundle: .module)

/*  Localizable.xcstrings on disk is JSON; Xcode shows it as a table.
    "Save" : {
      "localizations" : {
        "ru" : { "stringUnit" : { "state" : "needs_review", "value" : "Сохранить" } },
        "de" : { "stringUnit" : { "state" : "new",          "value" : "" } }
      }
    },
    "Old key" : { "extractionState" : "stale", ... }     // not found this build
*/

// The build output is unchanged from the .strings era — this still works
Bundle.main.localizedString(forKey: "Save", value: nil, table: nil)

// Wrong: a two-form language baked into the call site
let label = count == 1 ? "1 item" : "\(count) items"

// Right: one key, the catalog carries every language's categories
Text("\(count) items")                       // extracted as the key "%lld items"
let title = String(localized: "\(count) items",
                   comment: "Cart badge; count is the number of line items")

/*  Localizable.xcstrings — Vary by Plural fills only the categories a language has.
    ru:  one  -> "%lld файл"      (1, 21, 31 …)
         few  -> "%lld файла"     (2–4, 22–24 …)
         many -> "%lld файлов"    (5–20, 11–14 …)
         other-> "%lld файла"     (fractions)
    en:  one  -> "%lld item"
         other-> "%lld items"
*/

// Two counts = two substitutions in one entry, so the order stays translatable
Text("\(fileCount) files in \(folderCount) folders")

// Automatic grammar agreement, for the languages that have inflection rules shipped
Text("^[\(count) item](inflect: true) selected")

// Zero is not a CLDR category in English — branch, do not expect the plural to do it
let empty = count == 0
  ? String(localized: "No items", comment: "Empty cart")
  : String(localized: "\(count) items")

// The number itself is locale data too: 1234 is "1,234" or "1 234" or "١٢٣٤"
Text("\(count.formatted()) items")

// Wrong: the model holds resolved characters, so nothing is ever extracted or translated
struct Section { let title: String }
let sections = [Section(title: "Recent")]   // no catalog entry
Text(section.title)                         // Text(_: String) — verbatim, not localized

// Right: the model holds a deferred resource, resolved at render time in the user's locale
struct Section { let title: LocalizedStringResource }
let sections = [Section(title: "Recent")]   // extracted; LocalizedStringResource is ExpressibleByStringLiteral
Text(section.title)                         // localized

// Need characters now — an accessibility label, a notification body, a log line for the user
content.body = String(localized: "Order \(id) shipped",
                      comment: "Push body; id is an order number")
cell.accessibilityLabel = String(localized: "Unread", comment: "Message state")

// A framework must name its own bundle, or it looks in the app's and finds nothing
Text("Save", bundle: .module)
LocalizedStringResource("Save", table: "Checkout", bundle: .atURL(Bundle.module.bundleURL))

// System-rendered strings must be deferred, not resolved at init
struct StartRun: AppIntent {
  static let title: LocalizedStringResource = "Start a run"
}

// Deliberately unlocalized: a name, a code, a number you already formatted
Text(verbatim: user.handle)

// Wrong: a pattern and a symbol chosen by the developer
let df = DateFormatter()
df.dateFormat = "MM/dd/yyyy HH:mm"          // 24-hour and US order, everywhere
Text("$\(order.total)")                     // dot decimal, dollar sign, always

// Right: locale decides presentation, your data decides the facts
Text(order.placedAt.formatted(date: .abbreviated, time: .shortened))
Text(order.total.formatted(.currency(code: order.currency)))   // EUR stays EUR
Text(Measurement(value: distanceKm, unit: UnitLength.kilometers)
      .formatted(.measurement(width: .abbreviated, usage: .road)))

// Relative dates and lists are locale data too
Text(order.placedAt, format: .relative(presentation: .named))  // "yesterday" / "gestern"
Text(names.formatted(.list(type: .and)))                       // "A, B, and C"

// Machine formats pin the locale explicitly; they are not user-facing
let iso = ISO8601DateFormatter()
let parser = DateFormatter()
parser.locale = Locale(identifier: "en_US_POSIX")
parser.dateFormat = "yyyy-MM-dd"

// The calendar is regional: week start and even the era are not yours to assume
var cal = Calendar.current
let weekStart = cal.firstWeekday                    // 1 in the US, 2 in Germany
let is24h = Locale.current.hourCycle == .zeroToTwentyThree

// Sorting: localizedStandardCompare, never <
let sorted = names.sorted { $0.localizedStandardCompare($1) == .orderedAscending }

// An identifier inside a right-to-left sentence: isolate it so neutrals stay put
let isolated = "\u{2068}" + order.number + "\u{2069}"      // FSI … PDI
Text("Order \(isolated) shipped")

// Digits follow the locale's numbering system — interpolation never does
Text(count.formatted())                                     // ١٢٣ in ar_EG
let latinDigits = count.formatted(.number.locale(Locale(identifier: "ar-SA-u-nu-latn")))

// Opt a directional glyph into mirroring; leave everything else alone
Image(systemName: "chevron.backward").flipsForRightToLeftLayoutDirection(true)

// The brand mark must not flip, in a mirrored screen
BrandLogo()
  .environment(\.layoutDirection, .leftToRight)

// UIKit equivalents
backButton.setImage(UIImage(named: "chevron")?.imageFlippedForRightToLeftLayoutDirection(),
                    for: .normal)
transport.semanticContentAttribute = .playback              // never mirrors
logoView.semanticContentAttribute = .forceLeftToRight

// Ask the view, not the locale — a subtree may be forced the other way
let isRTL = view.effectiveUserInterfaceLayoutDirection == .rightToLeft

// Wrong: a transform is in raw coordinates and ignores layout direction
card.transform = CGAffineTransform(translationX: 100, y: 0)
// Right: flip the sign yourself
card.transform = CGAffineTransform(translationX: isRTL ? -100 : 100, y: 0)

import XCTest

final class LocalizationLayoutTests: XCTestCase {
  // One test, run per language by CI; xcodebuild -testLanguage overrides it per job
  func testCheckoutSurvivesLongStrings() throws {
    let app = XCUIApplication()
    app.launchArguments += [
      "-AppleLanguages", "(de)",     // longest of our shipping languages
      "-AppleLocale", "de_DE",
      "-UIPreferredContentSizeCategoryName", "UICTContentSizeCategoryAccessibilityL",
    ]
    app.launch()
    app.buttons["checkout"].tap()

    // A clipped label still reports its full string, so a text assertion proves nothing.
    // The audit compares rendered text against its frame and fails when it does not fit.
    try app.performAccessibilityAudit(for: [.textClipped, .dynamicType])
  }
}

// CI matrix — pseudolanguages are selected the same way as real ones:
//   xcodebuild test -scheme App -testLanguage de -testRegion DE
//   xcodebuild test -scheme App -testLanguage ar -testRegion SA
//
// Locally: Scheme ▸ Run ▸ Options ▸ App Language ▸ Double-Length Pseudolanguage
//          "Save"  ->  "Save Save"        clipping shows up
//          Accented Pseudolanguage        plain ASCII means a hardcoded string
//          Bounded String Pseudolanguage  [Save] reveals a concatenated sentence

// The screens worth a pixel diff as well, because overlap never trips the audit
func testCheckoutSnapshot() { assertSnapshot(of: CheckoutView(), as: .image) }

// 1. Push: the server sends keys, the device does the localizing
let payload = """
{ "aps": { "alert": {
      "title-loc-key": "PUSH_ORDER_TITLE",
      "loc-key":       "PUSH_ORDER_BODY",
      "loc-args":      ["A-1024", "Anna"]
  }, "mutable-content": 1 } }
"""
// Localizable.xcstrings must contain, in every language:
//   "PUSH_ORDER_BODY" = "%1$@ was shipped by %2$@"   // positional, so it can be reordered
// The key has to exist in the INSTALLED build — never rename, only add.

// Formatting the server cannot do: run your own code in the user's locale first
final class NotificationService: UNNotificationServiceExtension {
  override func didReceive(_ request: UNNotificationRequest,
                           withContentHandler handler: @escaping (UNNotificationContent) -> Void) {
    let content = request.content.mutableCopy() as! UNMutableNotificationContent
    if let epoch = request.content.userInfo["deliveryAt"] as? TimeInterval {
      let when = Date(timeIntervalSince1970: epoch).formatted(date: .abbreviated, time: .shortened)
      content.body = String(localized: "Arriving \(when)", comment: "Push body; delivery time")
    }
    handler(content)
  }
}

// 2. Siri: intent titles extract normally...
struct TrackOrder: AppIntent {
  static let title: LocalizedStringResource = "Track order"
}
// ...but phrases must be in AppShortcuts.xcstrings and must name the app
struct Shortcuts: AppShortcutsProvider {
  static var appShortcuts: [AppShortcut] {
    AppShortcut(intent: TrackOrder(), phrases: ["Track my order in \(.applicationName)"])
  }
}
